/* =========================================
   LIGHTWEIGHT CLIPBOARD JS (KUSTOM)
   Untuk Undangan Astri & Yufen
========================================= */

class ClipboardJS {
    constructor(selector) {
        this.triggers = document.querySelectorAll(selector);
        this.handlers = {};
        
        this.triggers.forEach(trigger => {
            trigger.addEventListener('click', (e) => {
                e.preventDefault();
                // Mengambil teks dari atribut data-clipboard-text (nomor rekening)
                const textToCopy = trigger.getAttribute('data-clipboard-text');
                
                if (textToCopy) {
                    // Menggunakan API Clipboard bawaan browser modern
                    navigator.clipboard.writeText(textToCopy).then(() => {
                        // Memicu event 'success' yang ada di index.php
                        if (this.handlers['success']) {
                            this.handlers['success']({
                                clearSelection: () => {} // Fungsi kosong agar tidak error
                            });
                        }
                    }).catch(err => {
                        console.error('Gagal menyalin text: ', err);
                        alert("Mohon maaf, fitur salin otomatis tidak didukung di browser ini. Silakan salin manual.");
                    });
                }
            });
        });
    }

    // Fungsi untuk mendaftarkan event (seperti 'success')
    on(event, handler) {
        this.handlers[event] = handler;
        return this; // Mengembalikan object agar bisa di-chaining
    }
}